createSource.source:
() => {
    if (!project.id || !dir?.available || !profile) { setLaunchError(!project.id ? '请先添加并选择项目' : !dir?.available ? '请先添加可用的代码目录' : m13Active ? '请先新建智能体' : '请先添加 AI 配置'); return; }
    // M14 首页：同一份选择驱动预检、运行身份、快照与权限（复核 RR05）；附件未就绪不创建任务、不清空（复核 RR06）
    const m14Sel = m14Preview ? (m14HomeSel ?? { agent: 'cc-sub', model: 'default', effort: '中' }) : null;
    const m14Agent = m14Sel && M14_AGENTS.find(a => a.id === m14Sel.agent);
    if (m14Agent?.status?.kind === 'unavailable' || m14Agent?.status?.kind === 'notready') { setLaunchError(`${m14Agent.name}${m14Agent.status.label}：${m14Agent.status.reason}`); setLaunchFix({ label: '管理智能体', route: 'settings/ai/configs' }); return; }
    if (m14Preview) { const notReady = m14HomeChips.filter(c => c.state === 'preparing' || c.state === 'failed'); if (notReady.length) { setLaunchError(notReady.some(c => c.state === 'failed') ? '有附件准备失败：重试或移除后再开始任务' : '附件还在准备中，准备好后再开始任务'); setLaunchFix(null); return; } }
    // 审核 Q03：新建与恢复共用启动预检，供应商缺 Key／已删除时不创建运行中任务
    const block = !m14Preview && m13Active && launchBlock(m13.configs.find(c => c.id === profile.id), m13.providers);
    if (block) { setLaunchError(block.reason); setLaunchFix(block.providerId ? { label: '去填写 Key', route: 'settings/ai/providers/' + block.providerId } : { label: '管理智能体', route: 'settings/ai/configs' }); return; }
    const t = { id: id(), title: prompt.trim() || '新任务', firstMessage: prompt.trim(), project: project.id, profile: profile.id, profileName: profile.name, runner: profile.runner, cwd: dir.path, configVersion: project.configVersion, time: '刚刚', status: 'running', integrationSnapshot: integrationSnapshot(integration.data, project.id),
      // M13 P0.16（审核 N01／N07）：记录智能体快照与启动时的插件、连接快照
      ...(m13Active ? { agent: agentSnapshot(m13.configs.find(c => c.id === profile.id), m13.providers), pluginSnapshot: pluginSnapshot(m13.plugins, m13.defaults, m13.bindings, project.id), permission: permissionSnapshot(m13Permission, m13Tool) } : {}),
      ...(m14Preview ? (() => { const mm = m14Agent.models.find(x => x.id === m14Sel.model) || m14Agent.models[0]; return { m14Sel, m14First: { text: prompt.trim(), chips: m14HomeChips }, profile: m14Agent.id, profileName: m14Agent.name, runner: m14Agent.tool || 'claude',
        agent: { agentId: m14Agent.id, agentName: m14Agent.name, tool: m14Agent.tool || 'claude', source: m14Agent.provider ? 'provider' : 'login', method: null, providerId: m14Agent.provider ? 'deepseek' : null, providerName: m14Agent.provider ? 'DeepSeek' : null, model: mm.id, models: [mm.id], modelNames: [mm.name], runModel: m14Agent.provider ? mm.id : null, runModelName: m14Agent.provider ? mm.name : null } }; })() : {}) };
    if (m14Preview) t.m14Ext = carryHomeExtensions(t.id);
    setLaunchError(''); setLaunchFix(null);
    setTasks(old => [t, ...old]); setPrompt(''); if (m14Preview) setM14HomeChips([]); nav('task/' + t.id);
  }
